import { icon } from "./icons.js";
import { avatar, avatarStack, emptyState, metric, priorityLabel, projectMark, progressBar, ring, statusBadge, taskRow } from "./components.js";
import { getProject, getTask, getUser, projectProgress, todayKey } from "./store.js";
import { STATUSES, PRIORITIES, escapeHtml, formatDate, formatMonth, isOverdue, matchesQuery, percent, relativeTime, toWeekday, mondayFirstIndex } from "./utils.js";

const navItems = [
  { id: "overview", label: "Overview", icon: "grid" },
  { id: "projects", label: "Projects", icon: "layers" },
  { id: "tasks", label: "Tasks", icon: "check" },
  { id: "calendar", label: "Calendar", icon: "calendar" },
  { id: "analytics", label: "Analytics", icon: "chart" },
  { id: "activity", label: "Activity", icon: "activity" }
];

export function renderSidebar(state, route, ui) {
  const active = route.page === "project" ? "projects" : route.page === "board" ? "tasks" : route.page;
  const unread = state.notifications.filter((item) => !item.read).length;
  const projects = state.projects.filter((project) => project.status !== "Completed").slice(0, 5);
  return `<aside class="sidebar ${ui.mobileNavOpen ? "sidebar-open" : ""}" id="sidebar">
    <div class="brand-row"><a class="brand" href="#/overview" aria-label="Nexus home"><span class="brand-mark">${icon("layers", 19)}</span><span>Nexus</span><span class="brand-plan">WORKSPACE</span></a><button class="icon-button sidebar-collapse" aria-label="Collapse sidebar" data-action="toggle-sidebar">${icon("chevronLeft", 17)}</button></div>
    <button class="workspace-switcher" data-action="workspace-menu"><span class="workspace-avatar">N</span><span class="workspace-copy"><strong>Northstar Studio</strong><small>Free workspace</small></span>${icon("chevronDown", 15)}</button>
    <div class="sidebar-scroll">
      <div class="sidebar-label">WORKSPACE</div>
      <nav class="primary-nav" aria-label="Main navigation">${navItems.map((item) => `<a class="nav-link ${active === item.id ? "active" : ""}" href="#/${item.id}" ${active === item.id ? 'aria-current="page"' : ""}>${icon(item.icon, 17)}<span>${item.label}</span>${item.id === "tasks" ? `<span class="nav-count">${state.tasks.filter((task) => task.status !== "Done").length}</span>` : ""}</a>`).join("")}</nav>
      <div class="sidebar-section-heading"><span class="sidebar-label">YOUR PROJECTS</span><button class="icon-button icon-button-xs" aria-label="Create project" data-action="create-project">${icon("plus", 15)}</button></div>
      <nav class="project-nav" aria-label="Your projects">${projects.map((project) => `<a class="project-nav-link ${route.projectId === project.id ? "active" : ""}" href="#/project/${project.id}"><i class="project-nav-dot" style="--project-color:${project.color}"></i><span>${escapeHtml(project.name)}</span></a>`).join("")}</nav>
      <button class="nav-link nav-link-muted" data-action="view-all-projects">${icon("more", 17)}<span>View all projects</span></button>
    </div>
    <div class="sidebar-bottom"><button class="nav-link ${active === "settings" ? "active" : ""}" data-action="navigate" data-page="settings">${icon("settings", 17)}<span>Settings</span></button><button class="nav-link" data-action="help">${icon("help", 17)}<span>Help & shortcuts</span><span class="shortcut-hint">?</span></button><div class="sidebar-profile"><span class="avatar avatar-md avatar-self">${escapeHtml(state.profile.name.split(/\s+/).map((part) => part[0]).slice(0, 2).join(""))}</span><span class="profile-copy"><strong>${escapeHtml(state.profile.name)}</strong><small>${escapeHtml(state.profile.role)}</small></span><button class="icon-button icon-button-xs" aria-label="Open profile settings" data-action="profile-settings">${icon("more", 16)}</button></div></div>
  </aside>`;
}

export function renderTopbar(state, route, ui) {
  const project = route.projectId ? getProject(route.projectId) : null;
  const labels = { overview: "Overview", projects: "Projects", tasks: "Tasks", board: "Board", calendar: "Calendar", analytics: "Analytics", activity: "Activity", settings: "Settings", project: project?.name || "Project" };
  const searchShortcut = typeof navigator !== "undefined" && /Mac|iPhone|iPad/i.test(navigator.platform || "") ? "⌘ K" : "Ctrl K";
  const unread = state.notifications.filter((item) => !item.read).length;
  const notificationPanel = ui.popover === "notifications" ? renderNotifications(state) : "";
  return `<header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" aria-label="Open navigation" data-action="toggle-mobile-nav">${icon("menu", 19)}</button><div class="breadcrumbs"><span>Northstar Studio</span>${icon("chevronRight", 14)}<strong>${escapeHtml(labels[route.page] || "Overview")}</strong></div></div><div class="topbar-actions"><button class="search-trigger" data-action="open-search" aria-label="Search projects and tasks"><span>${icon("search", 16)}<span>Search anything</span></span><kbd>${searchShortcut}</kbd></button><span class="topbar-divider"></span><button class="button button-primary button-sm" data-action="create-task">${icon("plus", 16)}<span>New</span><span class="button-chevron">${icon("chevronDown", 13)}</span></button><div class="popover-anchor"><button class="icon-button notification-button" aria-label="Notifications${unread ? `, ${unread} unread` : ""}" data-action="toggle-notifications">${icon("bell", 18)}${unread ? `<span class="notification-dot"></span>` : ""}</button>${notificationPanel}</div><button class="avatar avatar-md avatar-self topbar-user" aria-label="Profile settings" data-action="profile-settings">${escapeHtml(state.profile.name.split(/\s+/).map((part) => part[0]).slice(0, 2).join(""))}</button></div></header>`;
}

function pageHeading(eyebrow, title, description, actions = "") {
  return `<div class="page-heading"><div><div class="page-eyebrow">${escapeHtml(eyebrow)}</div><h1>${title}</h1>${description ? `<p>${description}</p>` : ""}</div><div class="page-heading-actions">${actions}</div></div>`;
}

function lineChart(values, color = "#596cce", fill = true) {
  const width = 620, height = 205, left = 18, right = 16, top = 16, bottom = 28;
  const max = Math.max(1, ...values);
  const points = values.map((value, index) => [left + index * ((width - left - right) / Math.max(1, values.length - 1)), top + (height - top - bottom) * (1 - value / (max * 1.16))]);
  const path = points.map(([x, y], index) => `${index ? "L" : "M"}${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
  const area = `${path} L${points.at(-1)[0].toFixed(1)},${height - bottom} L${points[0][0].toFixed(1)},${height - bottom} Z`;
  const marks = points.map(([x, y], index) => index === points.length - 1 ? `<circle cx="${x}" cy="${y}" r="5" fill="${color}" stroke="var(--surface)" stroke-width="3"/>` : "").join("");
  const grid = [0, 1, 2, 3].map((n) => `<line x1="${left}" x2="${width - right}" y1="${top + n * ((height - top - bottom) / 3)}" y2="${top + n * ((height - top - bottom) / 3)}" stroke="var(--line-soft)" stroke-dasharray="3 5"/>`).join("");
  return `<svg class="line-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Weekly completed task trend">${grid}${fill ? `<path d="${area}" fill="url(#trend-fill)"/>` : ""}<defs><linearGradient id="trend-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".18"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="${path}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${marks}</svg>`;
}

function projectCard(project, state) {
  const members = project.members.map((id) => getUser(id)).filter(Boolean);
  const tasks = state.tasks.filter((task) => task.projectId === project.id);
  const done = tasks.filter((task) => task.status === "Done").length;
  const progress = projectProgress(project.id);
  const owner = getUser(project.leadId);
  return `<article class="project-card"><button class="project-card-open" data-action="open-project" data-id="${escapeHtml(project.id)}" aria-label="Open ${escapeHtml(project.name)}"><div class="project-card-top">${projectMark(project, "lg")}<span class="project-card-menu" aria-hidden="true">${icon("arrowUpRight", 16)}</span></div><h3>${escapeHtml(project.name)}</h3><p>${escapeHtml(project.description)}</p></button><div class="project-card-meta"><span>${statusBadge(project.status)}</span><span class="project-due ${isOverdue(project.dueDate) && project.status !== "Completed" ? "is-overdue" : ""}">${icon("calendar", 14)} ${formatDate(project.dueDate)}</span></div><div class="project-progress-head"><span>Progress</span><strong>${progress}%</strong></div>${progressBar(progress, { thin: true, color: project.color })}<div class="project-card-footer"><div class="project-task-count">${icon("check", 14)} ${done}<span>/</span>${tasks.length} tasks</div><div class="project-card-people">${avatarStack(members, 3)}${owner ? `<span class="project-lead">Lead ${escapeHtml(owner.name.split(" ")[0])}</span>` : ""}</div></div></article>`;
}

export function renderOverview(state) {
  const dayLabel = new Intl.DateTimeFormat("en", { weekday: "long", month: "long", day: "numeric" }).format(new Date()).toUpperCase();
  const greetingTitle = `Good morning, ${escapeHtml(state.profile.name.split(/\s+/)[0])} <span class="greeting-spark">${icon("sparkle", 21)}</span>`;
  const activeProjects = state.projects.filter((project) => ["Active", "At risk"].includes(project.status));
  const completedTasks = state.tasks.filter((task) => task.status === "Done");
  const openTasks = state.tasks.filter((task) => task.status !== "Done");
  const dueSoon = openTasks.filter((task) => task.dueDate && task.dueDate >= todayKey() && task.dueDate <= new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10)).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  const todayTasks = openTasks.filter((task) => task.dueDate === todayKey());
  const recent = [...state.activity].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 5);
  const week = state.weeklyHistory.at(-1);
  const lastWeek = state.weeklyHistory.at(-2);
  const trend = percent(Math.max(0, week.completed - lastWeek.completed), lastWeek.completed || 1);
  const headingActions = `<button class="button button-secondary" data-action="navigate" data-page="analytics">${icon("chart", 16)} View insights ${icon("arrowRight", 14)}</button>`;
  return `<section class="page-content page-overview">${pageHeading(dayLabel, greetingTitle, "Here’s what’s happening across your workspace today.", headingActions)}
    <div class="metrics-grid">${metric({ label: "Active projects", value: String(activeProjects.length).padStart(2, "0"), change: "+2 this month", detail: "vs. last month", iconName: "layers", accent: "violet" })}${metric({ label: "Tasks completed", value: String(completedTasks.length).padStart(2, "0"), change: `+${week.completed - lastWeek.completed} this week`, detail: `${trend}% vs. last week`, iconName: "check", accent: "green" })}${metric({ label: "Due this week", value: String(dueSoon.length).padStart(2, "0"), change: `${dueSoon.filter((task) => task.priority === "Urgent").length} urgent`, detail: `${todayTasks.length} due today`, iconName: "calendar", accent: "amber" })}${metric({ label: "Open tasks", value: String(openTasks.length).padStart(2, "0"), change: `${state.tasks.filter((task) => task.status === "In Progress").length} in progress`, detail: `${state.tasks.filter((task) => task.status === "In Review").length} ready for review`, iconName: "activity", accent: "blue" })}</div>
    <div class="dashboard-grid dashboard-grid-main"><article class="surface chart-card"><div class="surface-heading"><div><h2>Productivity</h2><p>Tasks completed over the last 12 weeks</p></div><span class="chart-period-label">Last 12 weeks</span></div><div class="chart-summary"><strong>${week.completed}</strong><span>completed this week</span><span class="chart-growth">${icon("arrowUpRight", 14)} ${trend}%</span></div><div class="chart-wrap">${lineChart(state.weeklyHistory.map((item) => item.completed))}<div class="chart-xlabels">${state.weeklyHistory.filter((_, index) => index % 2 === 0 || index === 11).map((item) => `<span>${item.label}</span>`).join("")}</div></div><div class="chart-legend"><span><i class="legend-dot legend-dot-primary"></i>Completed tasks</span><span>Peak week <strong>${Math.max(...state.weeklyHistory.map((item) => item.completed))}</strong></span></div></article>
      <article class="surface workload-card"><div class="surface-heading"><div><h2>This week</h2><p>Workload at a glance</p></div><button class="icon-button" aria-label="Open calendar" data-action="navigate" data-page="calendar">${icon("arrowUpRight", 16)}</button></div><div class="workload-total"><strong>${openTasks.length}</strong><span>open tasks across<br/>${activeProjects.length} active projects</span></div><div class="workload-rows">${["In Progress", "In Review", "Todo", "Backlog"].map((status) => { const count = state.tasks.filter((task) => task.status === status).length; return `<div class="workload-row"><span class="workload-name"><i class="workload-dot workload-${status.toLowerCase().replaceAll(" ", "-")}"></i>${status}</span><span class="workload-track"><i style="width:${percent(count, state.tasks.length)}%"></i></span><strong>${count}</strong></div>`; }).join("")}</div><button class="text-link workload-link" data-action="navigate" data-page="tasks">See all tasks ${icon("arrowRight", 14)}</button></article></div>
    <div class="dashboard-grid dashboard-grid-secondary"><article class="surface focus-card"><div class="surface-heading"><div><h2>Project focus</h2><p>Keep momentum on the work that matters</p></div><button class="text-link" data-action="view-all-projects">All projects ${icon("arrowRight", 14)}</button></div><div class="focus-project-list">${activeProjects.slice(0, 4).map((project) => { const tasks = state.tasks.filter((task) => task.projectId === project.id); const progress = projectProgress(project.id); return `<button class="focus-project-row" data-action="open-project" data-id="${escapeHtml(project.id)}">${projectMark(project, "sm")}<span class="focus-project-name"><strong>${escapeHtml(project.name)}</strong><small>${tasks.filter((task) => task.status !== "Done").length} open tasks · due ${formatDate(project.dueDate)}</small></span><span class="focus-project-progress">${progress}%</span><span class="focus-progress-bar">${progressBar(progress, { thin: true, color: project.color })}</span>${icon("chevronRight", 15)}</button>`; }).join("")}</div></article>
      <article class="surface due-card"><div class="surface-heading"><div><h2>Coming up</h2><p>Tasks that need your attention</p></div><button class="text-link" data-action="navigate" data-page="tasks">View all ${icon("arrowRight", 14)}</button></div>${dueSoon.length ? `<div class="coming-list">${dueSoon.slice(0, 4).map((task) => { const project = getProject(task.projectId); const person = getUser(task.assigneeId); return `<button class="coming-row" data-action="open-task" data-id="${escapeHtml(task.id)}"><span class="coming-date"><strong>${new Date(`${task.dueDate}T12:00:00`).getDate()}</strong><small>${new Intl.DateTimeFormat("en", { month: "short" }).format(new Date(`${task.dueDate}T12:00:00`))}</small></span><span class="coming-copy"><strong>${escapeHtml(task.title)}</strong><small>${escapeHtml(project?.name || "")} · ${person ? escapeHtml(person.name.split(" ")[0]) : "Unassigned"}</small></span>${priorityLabel(task.priority, true)}</button>`; }).join("")}</div>` : emptyState({ iconName: "checkCircle", title: "All caught up", body: "Nothing is due in the next seven days." })}</article></div>
    <article class="surface activity-preview"><div class="surface-heading"><div><h2>Recent activity</h2><p>A little context goes a long way</p></div><button class="text-link" data-action="navigate" data-page="activity">All activity ${icon("arrowRight", 14)}</button></div><div class="activity-preview-list">${recent.map((item) => activityItem(item)).join("")}</div></article>
  </section>`;
}

export function renderProjects(state, ui) {
  const query = ui.search.projects || "";
  const status = ui.projectStatus || "All projects";
  const sort = ui.projectSort || "Recently updated";
  let projects = state.projects.filter((project) => matchesQuery(`${project.name} ${project.description} ${project.status}`, query) && (status === "All projects" || project.status === status));
  if (sort === "Name A–Z") projects.sort((a, b) => a.name.localeCompare(b.name));
  else if (sort === "Due date") projects.sort((a, b) => (a.dueDate || "9999").localeCompare(b.dueDate || "9999"));
  else if (sort === "Progress") projects.sort((a, b) => projectProgress(b.id) - projectProgress(a.id));
  else projects.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  const statusOptions = ["All projects", "Active", "At risk", "Planned", "Completed"];
  const action = `<button class="button button-primary" data-action="create-project">${icon("plus", 16)} New project</button>`;
  return `<section class="page-content">${pageHeading("WORKSPACE", "Projects", "Plan, organize, and track the work your team is moving forward.", action)}<div class="project-toolbar"><label class="input-with-icon project-search">${icon("search", 16)}<input data-search="projects" data-focus-key="search-projects" type="search" placeholder="Find a project…" value="${escapeHtml(query)}" aria-label="Search projects"/></label><div class="toolbar-spacer"></div><label class="filter-select-wrap"><span class="sr-only">Filter by status</span><select data-filter="projectStatus" aria-label="Filter projects by status">${statusOptions.map((option) => `<option ${status === option ? "selected" : ""}>${option}</option>`).join("")}</select>${icon("chevronDown", 14)}</label><label class="filter-select-wrap"><span class="sr-only">Sort projects</span><select data-filter="projectSort" aria-label="Sort projects">${["Recently updated", "Name A–Z", "Due date", "Progress"].map((option) => `<option ${sort === option ? "selected" : ""}>${option}</option>`).join("")}</select>${icon("chevronDown", 14)}</label><div class="view-toggle" role="group" aria-label="Project view"><button class="${ui.projectView !== "list" ? "selected" : ""}" aria-label="Grid view" aria-pressed="${ui.projectView !== "list"}" data-action="set-project-view" data-view="grid">${icon("grid", 16)}</button><button class="${ui.projectView === "list" ? "selected" : ""}" aria-label="List view" aria-pressed="${ui.projectView === "list"}" data-action="set-project-view" data-view="list">${icon("layers", 16)}</button></div></div><div class="results-caption"><span>${projects.length} ${projects.length === 1 ? "project" : "projects"}</span>${query || status !== "All projects" ? `<button class="text-link" data-action="clear-project-filters">Clear filters</button>` : ""}</div>${projects.length ? ui.projectView === "list" ? `<div class="surface project-list-table"><div class="project-list-head"><span>Project</span><span>Lead</span><span>Status</span><span>Progress</span><span>Due date</span><span>Team</span></div>${projects.map((project) => { const owner = getUser(project.leadId); const members = project.members.map(getUser).filter(Boolean); const progress = projectProgress(project.id); return `<button class="project-list-row" data-action="open-project" data-id="${escapeHtml(project.id)}"><span class="project-list-name">${projectMark(project, "sm")}<span><strong>${escapeHtml(project.name)}</strong><small>${escapeHtml(project.description)}</small></span></span><span>${owner ? avatar(owner, "sm") : "—"}<small class="project-lead-name">${escapeHtml(owner?.name || "Unassigned")}</small></span><span>${statusBadge(project.status)}</span><span class="project-list-progress"><span>${progress}%</span>${progressBar(progress, { thin: true, color: project.color })}</span><span class="${isOverdue(project.dueDate) && project.status !== "Completed" ? "is-overdue" : ""}">${formatDate(project.dueDate)}</span><span>${avatarStack(members, 3)}</span></button>`; }).join("")}</div>` : `<div class="projects-grid">${projects.map((project) => projectCard(project, state)).join("")}</div>` : emptyState({ iconName: "layers", title: query ? "No projects found" : "Nothing here yet", body: query ? "Try a different project name or clear your filters." : "Create a project to give your team's work a home.", action: `<button class="button button-primary" data-action="create-project">${icon("plus", 16)} New project</button>` })}</section>`;
}

export function renderTasks(state, ui) {
  const query = ui.search.tasks || "";
  const status = ui.taskStatus || "All statuses";
  const priority = ui.taskPriority || "All priorities";
  const projectId = ui.taskProject || "All projects";
  const sort = ui.taskSort || "Due date";
  let tasks = state.tasks.filter((task) => matchesQuery(`${task.title} ${task.tag} ${task.description}`, query)
    && (status === "All statuses" || task.status === status)
    && (priority === "All priorities" || task.priority === priority)
    && (projectId === "All projects" || task.projectId === projectId));
  const sorters = {
    "Due date": (a, b) => (a.dueDate || "9999").localeCompare(b.dueDate || "9999"),
    "Priority": (a, b) => PRIORITIES.indexOf(a.priority) - PRIORITIES.indexOf(b.priority),
    "Recently updated": (a, b) => b.updatedAt.localeCompare(a.updatedAt),
    "Name A–Z": (a, b) => a.title.localeCompare(b.title)
  };
  tasks.sort(sorters[sort]);
  const hasFilters = query || status !== "All statuses" || priority !== "All priorities" || projectId !== "All projects";
  return `<section class="page-content">${pageHeading("WORKSPACE", "Tasks", "A clear view of every next step across your projects.", `<button class="button button-primary" data-action="create-task">${icon("plus", 16)} New task</button>`)}<div class="task-toolbar"><label class="input-with-icon task-search">${icon("search", 16)}<input data-search="tasks" data-focus-key="search-tasks" type="search" placeholder="Search tasks…" value="${escapeHtml(query)}" aria-label="Search tasks"/></label><label class="filter-select-wrap"><span class="sr-only">Filter by status</span><select data-filter="taskStatus" aria-label="Filter tasks by status">${["All statuses", ...STATUSES].map((option) => `<option ${status === option ? "selected" : ""}>${option}</option>`).join("")}</select>${icon("chevronDown", 14)}</label><label class="filter-select-wrap"><span class="sr-only">Filter by priority</span><select data-filter="taskPriority" aria-label="Filter tasks by priority">${["All priorities", ...PRIORITIES].map((option) => `<option ${priority === option ? "selected" : ""}>${option}</option>`).join("")}</select>${icon("chevronDown", 14)}</label><label class="filter-select-wrap task-project-filter"><span class="sr-only">Filter by project</span><select data-filter="taskProject" aria-label="Filter tasks by project"><option>All projects</option>${state.projects.map((project) => `<option value="${escapeHtml(project.id)}" ${projectId === project.id ? "selected" : ""}>${escapeHtml(project.name)}</option>`).join("")}</select>${icon("chevronDown", 14)}</label><label class="filter-select-wrap task-sort-filter"><span class="sr-only">Sort tasks</span><select data-filter="taskSort" aria-label="Sort tasks">${["Due date", "Priority", "Recently updated", "Name A–Z"].map((option) => `<option ${sort === option ? "selected" : ""}>${option}</option>`).join("")}</select>${icon("sort", 14)}</label></div><div class="task-list-summary"><div><strong>${tasks.length}</strong> ${tasks.length === 1 ? "task" : "tasks"}${hasFilters ? `<button class="text-link clear-task-filters" data-action="clear-task-filters">${icon("filterX", 14)} Clear filters</button>` : ""}</div><button class="view-board-link" data-action="navigate" data-page="board">${icon("layers", 15)} Open board</button></div>${tasks.length ? `<div class="surface task-table"><div class="task-table-head"><span>Task name</span><span>Priority</span><span>Status</span><span>Due date</span><span>Assignee</span><span></span></div><div class="task-table-body">${tasks.map((task) => { const project = getProject(task.projectId); const user = getUser(task.assigneeId); return `<div class="task-table-row"><button class="task-table-title" data-action="open-task" data-id="${escapeHtml(task.id)}"><span class="task-status-icon task-status-${task.status.toLowerCase().replaceAll(" ", "-")}">${task.status === "Done" ? icon("check", 13) : icon("circle", 15)}</span><span><strong>${escapeHtml(task.title)}</strong><small>${projectMark(project || { color: "#8893a3", icon: "layers" }, "xs")}${escapeHtml(project?.name || "No project")}<i class="small-separator"></i>${escapeHtml(task.tag)}</small></span></button><span class="task-table-priority">${priorityLabel(task.priority)}</span><span>${statusBadge(task.status)}</span><span class="task-table-date ${isOverdue(task.dueDate) && task.status !== "Done" ? "is-overdue" : ""}">${task.dueDate ? formatDate(task.dueDate) : "—"}</span><span class="task-table-assignee">${avatar(user, "sm")}<small>${escapeHtml(user?.name.split(" ")[0] || "Unassigned")}</small></span><button class="icon-button icon-button-xs row-more" aria-label="Open ${escapeHtml(task.title)}" data-action="open-task" data-id="${escapeHtml(task.id)}">${icon("more", 16)}</button></div>`; }).join("")}</div></div>` : emptyState({ iconName: "check", title: hasFilters ? "No tasks match those filters" : "No tasks yet", body: hasFilters ? "Try changing a filter or search term to see more work." : "Create a task to start tracking the next step.", action: hasFilters ? `<button class="button button-secondary" data-action="clear-task-filters">Clear filters</button>` : `<button class="button button-primary" data-action="create-task">${icon("plus", 16)} New task</button>` })}</section>`;
}

function boardCard(task) {
  const project = getProject(task.projectId), user = getUser(task.assigneeId);
  return `<article class="board-card" draggable="true" tabindex="0" role="button" aria-label="Open task ${escapeHtml(task.title)}" data-action="open-task" data-id="${escapeHtml(task.id)}" data-drag-task="${escapeHtml(task.id)}"><div class="board-card-top">${priorityLabel(task.priority)}<button class="icon-button icon-button-xs board-card-more" aria-label="Edit task" data-action="open-task" data-id="${escapeHtml(task.id)}">${icon("more", 15)}</button></div><h3>${escapeHtml(task.title)}</h3><div class="board-card-project">${projectMark(project || { color: "#8893a3", icon: "layers" }, "xs")}${escapeHtml(project?.name || "No project")}</div>${task.tag ? `<span class="task-tag board-tag">${escapeHtml(task.tag)}</span>` : ""}<div class="board-card-footer"><span class="board-due ${isOverdue(task.dueDate) && task.status !== "Done" ? "is-overdue" : ""}">${icon("calendar", 13)} ${task.dueDate ? formatDate(task.dueDate) : "No date"}</span>${avatar(user, "sm")}</div></article>`;
}

export function renderBoard(state, ui, projectId = null) {
  const statuses = ["Backlog", "Todo", "In Progress", "In Review", "Done"];
  const selectedProject = projectId || (ui.boardProject && ui.boardProject !== "All projects" ? ui.boardProject : null);
  const projects = selectedProject ? state.projects.filter((project) => project.id === selectedProject) : state.projects;
  const tasks = selectedProject ? state.tasks.filter((task) => task.projectId === selectedProject) : state.tasks;
  const total = tasks.length;
  return `<div class="board-view"><div class="board-toolbar"><div class="board-total"><span class="board-total-dot"></span>${total} tasks <span class="small-separator"></span> Drag a card to update its status</div><div class="board-filters">${projectId ? `<button class="button button-secondary button-sm" data-action="edit-project" data-id="${escapeHtml(projectId)}">${icon("settings", 14)} Project settings</button>` : `<label class="filter-select-wrap board-project-filter-button">${icon("filter", 15)}<select data-filter="boardProject" aria-label="Filter board by project"><option>All projects</option>${state.projects.map((project) => `<option value="${escapeHtml(project.id)}" ${ui.boardProject === project.id ? "selected" : ""}>${escapeHtml(project.name)}</option>`).join("")}</select>${icon("chevronDown", 14)}</label>`}<span>${avatarStack(projects.flatMap((project) => project.members.map(getUser).filter(Boolean)).filter((user, index, all) => all.findIndex((item) => item.id === user.id) === index), 5)}</span></div></div><div class="board-columns">${statuses.map((status) => { const items = tasks.filter((task) => task.status === status); return `<section class="board-column"><header class="board-column-head"><span class="board-status-marker board-marker-${status.toLowerCase().replaceAll(" ", "-")}"></span><h2>${status}</h2><span class="board-column-count">${items.length}</span><button class="icon-button icon-button-xs" aria-label="Create task in ${status}" data-action="create-task-in-status" data-status="${status}">${icon("plus", 15)}</button></header><div class="board-dropzone" data-drop-status="${status}" aria-label="${status} tasks">${items.map(boardCard).join("")}${items.length === 0 ? `<div class="board-empty">Drop a task here</div>` : ""}</div></section>`; }).join("")}</div></div>`;
}

function renderProjectTasks(state, projectId) {
  const tasks = state.tasks.filter((task) => task.projectId === projectId).sort((a, b) => (a.dueDate || "9999").localeCompare(b.dueDate || "9999"));
  return tasks.length ? `<div class="project-task-list">${tasks.map((task) => taskRow(task, getProject(task.projectId), getUser(task.assigneeId))).join("")}</div>` : emptyState({ iconName: "check", title: "No tasks in this project", body: "Create a task and give the project its next step.", action: `<button class="button button-primary" data-action="create-task-for-project" data-id="${escapeHtml(projectId)}">${icon("plus", 15)} Add task</button>` });
}

function renderTimeline(state, project) {
  const tasks = state.tasks.filter((task) => task.projectId === project.id).sort((a, b) => a.dueDate.localeCompare(b.dueDate));
  const today = new Date();
  const start = new Date(today.getFullYear(), today.getMonth(), 1);
  const end = project.dueDate ? new Date(`${project.dueDate}T12:00:00`) : new Date(start.getTime() + 45 * 86400000);
  const span = Math.max(1, end.getTime() - start.getTime());
  const months = Array.from({ length: 4 }, (_, index) => { const month = new Date(start.getFullYear(), start.getMonth() + index, 1); return month; });
  return `<div class="timeline-wrap"><div class="timeline-header"><span>Task</span><div class="timeline-months">${months.map((month) => `<span>${new Intl.DateTimeFormat("en", { month: "short" }).format(month)}</span>`).join("")}</div></div><div class="timeline-rows">${tasks.map((task) => { const due = new Date(`${task.dueDate}T12:00:00`); const daysFromStart = (due - start) / 86400000; const left = Math.max(0, Math.min(90, (daysFromStart / (span / 86400000 + 40)) * 100)); const duration = task.status === "Done" ? 15 : task.status === "In Progress" ? 20 : 12; return `<div class="timeline-row"><button data-action="open-task" data-id="${escapeHtml(task.id)}" class="timeline-task"><span class="task-status-icon task-status-${task.status.toLowerCase().replaceAll(" ", "-")}">${task.status === "Done" ? icon("check", 12) : icon("circle", 14)}</span>${escapeHtml(task.title)}</button><div class="timeline-track"><span class="timeline-bar timeline-bar-${task.status.toLowerCase().replaceAll(" ", "-")}" style="left:${left}%;width:${duration}%;--timeline-color:${project.color}" title="${escapeHtml(task.title)} — ${formatDate(task.dueDate)}"></span></div></div>`; }).join("")}</div></div>`;
}

function renderProjectFiles(project) {
  const files = project.files || [];
  return `<div class="files-toolbar"><div><strong>Project files</strong><p>Reference material shared with this team</p></div><label class="button button-secondary button-sm upload-label">${icon("upload", 15)} Upload file<input type="file" data-upload-project="${escapeHtml(project.id)}" aria-label="Upload a file to ${escapeHtml(project.name)}"/></label></div>${files.length ? `<div class="file-list">${files.map((file, index) => `<div class="file-row"><span class="file-icon file-icon-${file.type || "doc"}">${icon(file.type === "pdf" ? "file" : "file", 17)}</span><button type="button" class="file-copy" data-action="download-project-file" data-id="${escapeHtml(project.id)}" data-index="${index}"><strong>${escapeHtml(file.name)}</strong><small>${escapeHtml(file.size || "Shared by the team")} · ${escapeHtml(file.updated || "Recently")}</small></button><button class="icon-button icon-button-xs" aria-label="Remove ${escapeHtml(file.name)}" data-action="remove-project-file" data-id="${escapeHtml(project.id)}" data-index="${index}">${icon("trash", 15)}</button></div>`).join("")}</div>` : emptyState({ iconName: "paperclip", title: "Bring the project context together", body: "Add a brief, design reference, or other file your team needs nearby.", action: `<label class="button button-secondary upload-label">${icon("upload", 15)} Upload first file<input type="file" data-upload-project="${escapeHtml(project.id)}" aria-label="Upload a file to ${escapeHtml(project.name)}"/></label>` })}`;
}

export function renderProjectDetail(state, ui, projectId) {
  const project = getProject(projectId);
  if (!project) return `<section class="page-content">${emptyState({ iconName: "layers", title: "Project not found", body: "It may have been removed or the link is out of date.", action: `<a class="button button-secondary" href="#/projects">Back to projects</a>` })}</section>`;
  const tasks = state.tasks.filter((task) => task.projectId === project.id);
  const done = tasks.filter((task) => task.status === "Done").length;
  const activeTasks = tasks.filter((task) => task.status !== "Done");
  const members = project.members.map(getUser).filter(Boolean);
  const lead = getUser(project.leadId);
  const tab = ui.projectTab || "Overview";
  const tabs = ["Overview", "Tasks", "Board", "Timeline", "Files", "Activity"];
  let content = "";
  if (tab === "Overview") {
    const updates = state.activity.filter((item) => item.projectId === project.id).slice(0, 4);
    const urgent = tasks.filter((task) => task.priority === "Urgent" && task.status !== "Done").slice(0, 3);
    content = `<div class="project-detail-grid"><div class="project-detail-main"><article class="surface project-overview-panel"><div class="project-description-head"><div><div class="panel-eyebrow">ABOUT THIS PROJECT</div><h2>${escapeHtml(project.name)}</h2></div><button class="icon-button" data-action="edit-project" data-id="${escapeHtml(project.id)}" aria-label="Edit project">${icon("settings", 17)}</button></div><p class="project-description-text">${escapeHtml(project.description)}</p><div class="project-detail-stats"><div><span>Project lead</span><strong class="lead-profile">${avatar(lead, "sm")} ${escapeHtml(lead?.name || "Unassigned")}</strong></div><div><span>Due date</span><strong class="project-due-large">${icon("calendar", 15)} ${project.dueDate ? formatDate(project.dueDate, { month: "long", day: "numeric", year: "numeric" }) : "No due date"}</strong></div><div><span>Team</span><strong>${avatarStack(members, 6)}<small>${members.length} members</small></strong></div></div></article><article class="surface project-progress-panel"><div class="surface-heading"><div><h2>Project progress</h2><p>Keep the whole team oriented around the outcome</p></div>${statusBadge(project.status)}</div><div class="big-progress-row"><div class="big-progress-copy"><strong>${projectProgress(project.id)}<small>%</small></strong><span>${done} of ${tasks.length} tasks complete</span></div>${ring(projectProgress(project.id), project.color, 62)}</div>${progressBar(projectProgress(project.id), { color: project.color })}<div class="progress-breakdown">${["Done", "In Progress", "In Review", "Todo", "Backlog"].map((status) => `<span><i class="board-marker-${status.toLowerCase().replaceAll(" ", "-")}"></i>${status}<strong>${tasks.filter((task) => task.status === status).length}</strong></span>`).join("")}</div></article><article class="surface project-next-panel"><div class="surface-heading"><div><h2>Next up</h2><p>The next few steps for this project</p></div><button class="text-link" data-action="set-project-tab" data-tab="Tasks">All tasks ${icon("arrowRight", 14)}</button></div>${activeTasks.length ? `<div class="project-task-list">${activeTasks.slice(0, 4).map((task) => taskRow(task, project, getUser(task.assigneeId), { compact: true })).join("")}</div>` : emptyState({ iconName: "checkCircle", title: "Project complete", body: "All tasks are done. Nice work, team." })}</article></div><div class="project-detail-aside"><article class="surface project-people-panel"><div class="surface-heading"><div><h2>People</h2><p>${members.length} teammates involved</p></div><button class="icon-button" aria-label="Manage project team" data-action="edit-project" data-id="${escapeHtml(project.id)}">${icon("plus", 16)}</button></div><div class="project-people-list">${members.map((member) => `<div class="project-person-row">${avatar(member, "sm")}<span><strong>${escapeHtml(member.name)}</strong><small>${escapeHtml(member.role)}</small></span>${member.id === project.leadId ? `<span class="person-role-badge">Lead</span>` : ""}</div>`).join("")}</div></article><article class="surface project-urgent-panel"><div class="surface-heading"><div><h2>Needs attention</h2><p>Urgent tasks to keep an eye on</p></div>${icon("flag", 16, "attention-icon")}</div>${urgent.length ? urgent.map((task) => `<button class="urgent-task" data-action="open-task" data-id="${escapeHtml(task.id)}"><span class="urgent-indicator"></span><span><strong>${escapeHtml(task.title)}</strong><small>${task.dueDate ? `Due ${formatDate(task.dueDate)}` : "No due date"}</small></span>${icon("chevronRight", 14)}</button>`).join("") : `<div class="quiet-success">${icon("checkCircle", 16)} No urgent tasks right now</div>`}</article><article class="surface project-update-panel"><div class="surface-heading"><div><h2>Recent updates</h2><p>Latest activity in this project</p></div></div>${updates.length ? `<div class="project-updates">${updates.map(activityItem).join("")}</div>` : `<p class="muted-copy">Project updates will show here.</p>`}<button class="text-link" data-action="set-project-tab" data-tab="Activity">View activity ${icon("arrowRight", 14)}</button></article></div></div>`;
  } else if (tab === "Tasks") {
    content = `<article class="surface project-tab-surface"><div class="surface-heading"><div><h2>Tasks</h2><p>${tasks.length} tasks · ${done} complete</p></div><button class="button button-primary button-sm" data-action="create-task-for-project" data-id="${escapeHtml(project.id)}">${icon("plus", 15)} Add task</button></div>${renderProjectTasks(state, project.id)}</article>`;
  } else if (tab === "Board") {
    content = renderBoard(state, ui, project.id);
  } else if (tab === "Timeline") {
    content = `<article class="surface project-tab-surface"><div class="surface-heading"><div><h2>Timeline</h2><p>Task deadlines across this project</p></div><span class="timeline-project-due">${icon("calendar", 15)} Due ${project.dueDate ? formatDate(project.dueDate) : "not set"}</span></div>${renderTimeline(state, project)}</article>`;
  } else if (tab === "Files") {
    content = `<article class="surface project-tab-surface files-panel">${renderProjectFiles(project)}</article>`;
  } else {
    const updates = state.activity.filter((item) => item.projectId === project.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    content = `<article class="surface project-tab-surface"><div class="surface-heading"><div><h2>Project activity</h2><p>A chronological record of changes</p></div></div>${updates.length ? `<div class="activity-feed">${updates.map((item) => activityItem(item, true)).join("")}</div>` : emptyState({ iconName: "activity", title: "No updates yet", body: "Changes and conversations will appear here." })}</article>`;
  }
  return `<section class="page-content project-detail-page"><div class="project-detail-header"><div class="project-detail-title">${projectMark(project, "xl")}<div><div class="project-breadcrumb"><a href="#/projects">Projects</a>${icon("chevronRight", 13)} ${escapeHtml(project.name)}</div><h1>${escapeHtml(project.name)}</h1><p>${escapeHtml(project.description)}</p></div></div><div class="project-detail-actions"><div class="project-team-stack">${avatarStack(members, 4)}<span>${members.length} people</span></div><button class="button button-secondary" data-action="edit-project" data-id="${escapeHtml(project.id)}">${icon("settings", 15)} Edit project</button><button class="button button-primary" data-action="create-task-for-project" data-id="${escapeHtml(project.id)}">${icon("plus", 15)} Add task</button></div></div><div class="project-detail-tabs" role="tablist" aria-label="Project sections">${tabs.map((item) => `<button role="tab" aria-selected="${tab === item}" class="${tab === item ? "active" : ""}" data-action="set-project-tab" data-tab="${item}">${item}${item === "Tasks" ? `<span>${tasks.length}</span>` : ""}</button>`).join("")}</div><div class="project-tab-content">${content}</div></section>`;
}

function renderCalendar(state, ui) {
  const cursor = ui.calendarCursor instanceof Date ? ui.calendarCursor : new Date();
  const year = cursor.getFullYear(), month = cursor.getMonth();
  const first = new Date(year, month, 1);
  const start = new Date(year, month, 1 - mondayFirstIndex(first.getDay()));
  const selected = ui.selectedCalendarDate || todayKey();
  const slots = Array.from({ length: 42 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); return date; });
  const datedTasks = state.tasks.filter((task) => task.dueDate);
  const selectedTasks = datedTasks.filter((task) => task.dueDate === selected).sort((a, b) => PRIORITIES.indexOf(a.priority) - PRIORITIES.indexOf(b.priority));
  const monthTasks = datedTasks.filter((task) => { const date = new Date(`${task.dueDate}T12:00:00`); return date.getFullYear() === year && date.getMonth() === month; });
  const weekdayLabels = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  return `<section class="page-content"><div class="page-heading calendar-page-heading"><div><div class="page-eyebrow">PLAN YOUR WORK</div><h1>Calendar</h1><p>See deadlines and make room for the work ahead.</p></div><div class="calendar-heading-actions"><button class="button button-secondary" data-action="calendar-today">Today</button><button class="button button-primary" data-action="create-task">${icon("plus", 16)} New task</button></div></div><div class="calendar-layout"><article class="surface calendar-surface"><div class="calendar-toolbar"><div><h2>${formatMonth(cursor)}</h2><span>${monthTasks.length} tasks this month</span></div><div class="calendar-controls"><button class="icon-button" aria-label="Previous month" data-action="calendar-prev">${icon("chevronLeft", 17)}</button><button class="icon-button" aria-label="Next month" data-action="calendar-next">${icon("chevronRight", 17)}</button></div></div><div class="calendar-grid"><div class="calendar-weekdays">${weekdayLabels.map((day) => `<span>${day}</span>`).join("")}</div><div class="calendar-days">${slots.map((date) => { const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; const items = datedTasks.filter((task) => task.dueDate === key); const other = date.getMonth() !== month; return `<button class="calendar-day ${other ? "outside-month" : ""} ${key === todayKey() ? "is-today" : ""} ${selected === key ? "is-selected" : ""}" data-action="select-calendar-day" data-day="${key}" aria-label="${toWeekday(date, "long")}, ${formatDate(key, { month: "long", day: "numeric", year: "numeric" })}, ${items.length} tasks" aria-pressed="${selected === key}"><span class="calendar-day-number">${date.getDate()}</span><span class="calendar-day-events">${items.slice(0, 2).map((task) => `<i class="calendar-event calendar-event-${task.priority.toLowerCase().replaceAll(" ", "-")}" title="${escapeHtml(task.title)}">${escapeHtml(task.title)}</i>`).join("")}${items.length > 2 ? `<small>+${items.length - 2} more</small>` : ""}</span></button>`; }).join("")}</div></div><div class="calendar-legend"><span><i class="calendar-event-dot"></i>Task deadline</span><span><i class="calendar-today-dot"></i>Today</span></div></article><aside class="surface calendar-agenda"><div class="agenda-heading"><div class="agenda-date"><span>${toWeekday(new Date(`${selected}T12:00:00`), "long")}</span><strong>${formatDate(selected, { month: "long", day: "numeric" })}</strong></div><span class="agenda-count">${selectedTasks.length}</span></div><div class="agenda-content">${selectedTasks.length ? selectedTasks.map((task) => `<button class="agenda-task" data-action="open-task" data-id="${escapeHtml(task.id)}"><span class="agenda-task-line" style="--project-color:${getProject(task.projectId)?.color || "#64748b"}"></span><span class="agenda-task-copy"><strong>${escapeHtml(task.title)}</strong><small>${escapeHtml(getProject(task.projectId)?.name || "")} · ${task.status}</small></span>${priorityLabel(task.priority, true)}</button>`).join("") : emptyState({ iconName: "calendar", title: "A little breathing room", body: selected === todayKey() ? "Nothing is due today. Use the time for focused work." : "No deadlines on this date. Select another day to see its work." })}</div><button class="agenda-create" data-action="create-task-on-date" data-day="${selected}">${icon("plus", 15)} Add task for this day</button><div class="agenda-upcoming"><div class="section-label">UP NEXT</div>${datedTasks.filter((task) => task.dueDate > selected && task.status !== "Done").sort((a, b) => a.dueDate.localeCompare(b.dueDate)).slice(0, 3).map((task) => `<button class="agenda-up-next" data-action="open-task" data-id="${escapeHtml(task.id)}"><span>${formatDate(task.dueDate, { month: "short", day: "numeric" })}</span><strong>${escapeHtml(task.title)}</strong></button>`).join("")}</div></aside></div></section>`;
}

function activityDescription(item) {
  const action = {
    completed: "completed a task",
    created: "created a task",
    updated: "updated",
    assigned: "changed the owner of",
    commented: "commented on",
    "created-project": "created project",
    deleted: "removed"
  }[item.type] || "updated";
  return `${action} <strong>${escapeHtml(item.target)}</strong>`;
}

export function activityItem(item, large = false) {
  const actor = getUser(item.actorId);
  const project = getProject(item.projectId);
  const iconName = item.type === "completed" ? "checkCircle" : item.type === "commented" ? "message" : item.type === "created-project" ? "layers" : item.type === "created" ? "plus" : item.type === "assigned" ? "user" : "activity";
  return `<button class="activity-item ${large ? "activity-item-large" : ""}" data-action="activity-target" data-id="${escapeHtml(item.projectId || "")}"><span class="activity-avatar-wrap">${avatar(actor, large ? "md" : "sm")}<i class="activity-type-icon activity-type-${escapeHtml(item.type)}">${icon(iconName, 11)}</i></span><span class="activity-copy"><span>${actor ? `<strong>${escapeHtml(actor.name)}</strong>` : "Someone"} ${activityDescription(item)}</span><small>${project ? `${projectMark(project, "xs")}${escapeHtml(project.name)}<i class="small-separator"></i>` : ""}${relativeTime(item.createdAt)}</small></span>${large ? `<span class="activity-chevron">${icon("chevronRight", 15)}</span>` : ""}</button>`;
}

function renderAnalytics(state) {
  const done = state.tasks.filter((task) => task.status === "Done");
  const active = state.projects.filter((project) => project.status === "Active" || project.status === "At risk");
  const avgProgress = active.length ? Math.round(active.reduce((sum, project) => sum + projectProgress(project.id), 0) / active.length) : 0;
  const team = state.users.map((user) => ({ user, count: done.filter((task) => task.assigneeId === user.id).length })).sort((a, b) => b.count - a.count);
  const statusColors = { "Backlog": "#c9ced8", "Todo": "#9ea7ba", "In Progress": "#6979cd", "In Review": "#bd8c4f", "Done": "#4c9b7a" };
  const statusCounts = STATUSES.map((status) => ({ status, count: state.tasks.filter((task) => task.status === status).length }));
  const priorityCounts = PRIORITIES.map((priority) => ({ priority, count: state.tasks.filter((task) => task.priority === priority).length }));
  const topCount = Math.max(...state.projects.map((project) => state.tasks.filter((task) => task.projectId === project.id).length));
  const completedWithTime = done.filter((task) => task.completedAt && task.createdAt);
  const averageDays = completedWithTime.length ? (completedWithTime.reduce((total, task) => total + ((new Date(task.completedAt).getTime() - new Date(task.createdAt).getTime()) / 86400000), 0) / completedWithTime.length).toFixed(1) : "—";
  const weekly = state.weeklyHistory.map((item) => item.completed);
  const taskTotal = state.tasks.length;
  let running = 0;
  const ringGradient = statusCounts.map(({ status, count }) => { const from = running; running += taskTotal ? count / taskTotal * 100 : 0; return `${statusColors[status]} ${from}% ${running}%`; }).join(", ");
  return `<section class="page-content">${pageHeading("WORKSPACE INTELLIGENCE", "Analytics", "Understand your team's momentum and where the work is going.", `<button class="button button-secondary" data-action="export-analytics">${icon("upload", 15)} Export summary</button>`)}<div class="analytics-metrics">${metric({ label: "Completed this week", value: String(state.weeklyHistory.at(-1).completed), change: "+18%", detail: "vs. last week", iconName: "checkCircle", accent: "green" })}${metric({ label: "Avg. completion time", value: `${averageDays}d`, change: "Across completed tasks", detail: `${completedWithTime.length} tasks with dates`, iconName: "clock", accent: "blue" })}${metric({ label: "Project health", value: `${avgProgress}%`, change: `${active.length} active projects`, detail: "average completion", iconName: "target", accent: "violet" })}${metric({ label: "Tasks in flight", value: String(state.tasks.filter((task) => ["In Progress", "In Review"].includes(task.status)).length), change: "Moving this week", detail: `${state.tasks.filter((task) => task.priority === "Urgent" && task.status !== "Done").length} need attention`, iconName: "activity", accent: "amber" })}</div><div class="analytics-grid"><article class="surface analytics-trend"><div class="surface-heading"><div><h2>Work completed</h2><p>Weekly task completions over the last 12 weeks</p></div><span class="chart-period-label">Last 12 weeks</span></div><div class="chart-summary"><strong>${state.weeklyHistory.at(-1).completed}</strong><span>tasks completed this week</span><span class="chart-growth">${icon("arrowUpRight", 14)} 18%</span></div><div class="chart-wrap">${lineChart(weekly, "#6274cf") }<div class="chart-xlabels">${state.weeklyHistory.filter((_, index) => index % 2 === 0 || index === 11).map((item) => `<span>${item.label}</span>`).join("")}</div></div></article><article class="surface status-breakdown"><div class="surface-heading"><div><h2>Work by status</h2><p>${taskTotal} tasks across all projects</p></div><button class="icon-button" aria-label="View all tasks" data-action="navigate" data-page="tasks">${icon("arrowUpRight", 16)}</button></div><div class="status-donut-layout"><div class="status-donut" style="background:conic-gradient(${ringGradient})"><span><strong>${taskTotal}</strong><small>tasks</small></span></div><div class="status-legend">${statusCounts.map((item) => `<div><i style="--legend-color:${statusColors[item.status]}"></i><span>${item.status}</span><strong>${item.count}</strong></div>`).join("")}</div></div></article><article class="surface project-distribution"><div class="surface-heading"><div><h2>Project workload</h2><p>Tasks by project</p></div><button class="text-link" data-action="view-all-projects">All projects ${icon("arrowRight", 14)}</button></div><div class="project-distribution-list">${state.projects.map((project) => { const count = state.tasks.filter((task) => task.projectId === project.id).length; return `<button class="distribution-row" data-action="open-project" data-id="${escapeHtml(project.id)}"><span class="distribution-project">${projectMark(project, "xs")}<span>${escapeHtml(project.name)}</span></span><span class="distribution-track"><i style="width:${percent(count, topCount)}%;--project-color:${project.color}"></i></span><strong>${count}</strong></button>`; }).join("")}</div></article><article class="surface priority-breakdown"><div class="surface-heading"><div><h2>Priority mix</h2><p>Where urgency is concentrated</p></div></div><div class="priority-bars">${priorityCounts.map((item) => `<div class="priority-bar-row"><span>${priorityLabel(item.priority, true)}${escapeHtml(item.priority)}</span><span class="distribution-track"><i class="priority-fill priority-fill-${item.priority.toLowerCase().replaceAll(" ", "-")}" style="width:${percent(item.count, taskTotal)}%"></i></span><strong>${item.count}</strong></div>`).join("")}</div><div class="priority-note">${icon("flag", 15)} ${state.tasks.filter((task) => task.priority === "Urgent" && task.status !== "Done").length} urgent items are still open</div></article><article class="surface team-performance"><div class="surface-heading"><div><h2>Team contributions</h2><p>Completed tasks by owner</p></div><span class="chart-period-label">All time</span></div><div class="team-chart">${team.map(({ user, count }) => `<div class="team-chart-row"><span class="team-chart-user">${avatar(user, "sm")}<strong>${escapeHtml(user.name.split(" ")[0])}</strong></span><span class="team-bar-track"><i style="width:${percent(count, Math.max(1, team[0].count))}%;--team-color:${user.text}"></i></span><strong>${count}</strong></div>`).join("")}</div></article><article class="surface project-health"><div class="surface-heading"><div><h2>Project health</h2><p>Current completion across active work</p></div></div><div class="health-projects">${active.map((project) => `<button class="health-project-row" data-action="open-project" data-id="${escapeHtml(project.id)}">${projectMark(project, "sm")}<span class="health-project-name"><strong>${escapeHtml(project.name)}</strong><small>${state.tasks.filter((task) => task.projectId === project.id && task.status !== "Done").length} tasks remaining</small></span><span class="health-project-progress">${projectProgress(project.id)}%${progressBar(projectProgress(project.id), { thin: true, color: project.color })}</span></button>`).join("")}</div></article></div></section>`;
}

function renderActivityPage(state, ui) {
  const query = ui.search.activity || "";
  const filter = ui.activityFilter || "All activity";
  const filters = ["All activity", "Tasks", "Projects", "Comments"];
  let items = [...state.activity].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  if (filter === "Tasks") items = items.filter((item) => ["created", "completed", "updated", "assigned", "deleted"].includes(item.type));
  if (filter === "Projects") items = items.filter((item) => item.type === "created-project");
  if (filter === "Comments") items = items.filter((item) => item.type === "commented");
  items = items.filter((item) => matchesQuery(`${item.target} ${getUser(item.actorId)?.name || ""} ${getProject(item.projectId)?.name || ""}`, query));
  const groups = new Map();
  for (const item of items) {
    const date = new Date(item.createdAt);
    const label = date.toDateString() === new Date().toDateString() ? "Today" : date.toDateString() === new Date(Date.now() - 86400000).toDateString() ? "Yesterday" : new Intl.DateTimeFormat("en", { month: "long", day: "numeric" }).format(date);
    if (!groups.has(label)) groups.set(label, []);
    groups.get(label).push(item);
  }
  return `<section class="page-content">${pageHeading("WORKSPACE", "Activity", "A living timeline of the decisions and progress across your team.", "")}<div class="activity-controls"><div class="activity-filter-tabs" role="tablist" aria-label="Filter activity">${filters.map((item) => `<button role="tab" aria-selected="${filter === item}" class="${filter === item ? "active" : ""}" data-action="set-activity-filter" data-filter="${item}">${item}</button>`).join("")}</div><label class="input-with-icon activity-search">${icon("search", 16)}<input data-search="activity" data-focus-key="search-activity" type="search" placeholder="Search activity…" value="${escapeHtml(query)}" aria-label="Search activity"/></label></div>${items.length ? `<div class="activity-timeline">${[...groups].map(([label, group]) => `<section class="activity-day-group"><h2>${label}<span>${group.length} updates</span></h2><div class="surface activity-day-card">${group.map((item) => activityItem(item, true)).join("")}</div></section>`).join("")}</div>` : emptyState({ iconName: "activity", title: "No matching activity", body: "Try a different search or choose another activity filter." })}</section>`;
}

function renderSettings(state, ui) {
  const tab = ui.settingsTab || "Profile";
  const tabs = [{ name: "Profile", icon: "user" }, { name: "Appearance", icon: "sun" }, { name: "Notifications", icon: "bell" }, { name: "Preferences", icon: "settings" }];
  let content = "";
  if (tab === "Profile") {
    content = `<div class="settings-section"><div class="settings-section-heading"><h2>Personal information</h2><p>Manage how you show up across the workspace.</p></div><form class="settings-form" data-form="profile"><div class="profile-edit-avatar">${avatar({ ...state.users[0], name: state.profile.name }, "xl")}<span class="field-note">Your initials are shown across the workspace.</span></div><label class="field-label">Full name<input name="name" value="${escapeHtml(state.profile.name)}" required maxlength="60"/></label><label class="field-label">Role<input name="role" value="${escapeHtml(state.profile.role)}" maxlength="60"/></label><label class="field-label">Email address<input type="email" name="email" value="${escapeHtml(state.profile.email)}" readonly aria-describedby="email-note"/><small id="email-note" class="field-note">Email is managed by your workspace administrator.</small></label><div class="form-actions"><button class="button button-primary" type="submit">Save changes</button></div></form></div>`;
  } else if (tab === "Appearance") {
    content = `<div class="settings-section"><div class="settings-section-heading"><h2>Appearance</h2><p>Choose the look that feels right for your workspace.</p></div><div class="theme-options" role="radiogroup" aria-label="Color theme">${[{ id: "light", label: "Light", icon: "sun" }, { id: "dark", label: "Dark", icon: "moon" }, { id: "system", label: "System", icon: "laptop" }].map((item) => `<button role="radio" aria-checked="${state.preferences.theme === item.id}" class="theme-option ${state.preferences.theme === item.id ? "selected" : ""}" data-action="set-theme" data-theme="${item.id}"><span class="theme-preview theme-preview-${item.id}"><span></span><i></i><b></b></span><span class="theme-option-label">${icon(item.icon, 16)} ${item.label}</span>${state.preferences.theme === item.id ? `<span class="theme-check">${icon("check", 13)}</span>` : ""}</button>`).join("")}</div><div class="settings-inline-note">${icon("help", 16)} System theme follows your device appearance setting.</div></div>`;
  } else if (tab === "Notifications") {
    content = `<div class="settings-section"><div class="settings-section-heading"><h2>Notifications</h2><p>Choose the updates you want to keep close.</p></div><div class="settings-toggle-list"><label class="settings-toggle-row"><span class="settings-toggle-copy"><strong>Product updates</strong><small>When someone assigns work to you or mentions you in a comment.</small></span><input type="checkbox" data-setting="emailNotifications" ${state.preferences.emailNotifications ? "checked" : ""}/><span class="toggle-control"></span></label><label class="settings-toggle-row"><span class="settings-toggle-copy"><strong>Weekly digest</strong><small>A Monday summary of progress, upcoming deadlines, and blockers.</small></span><input type="checkbox" data-setting="weeklyDigest" ${state.preferences.weeklyDigest ? "checked" : ""}/><span class="toggle-control"></span></label></div><button class="button button-secondary" data-action="mark-all-read">${icon("checkCircle", 15)} Mark all notifications as read</button></div>`;
  } else {
    content = `<div class="settings-section"><div class="settings-section-heading"><h2>Preferences</h2><p>Fine-tune your daily workspace experience.</p></div><div class="settings-toggle-list"><label class="settings-toggle-row"><span class="settings-toggle-copy"><strong>Compact task rows</strong><small>Show more work at once in task lists.</small></span><input type="checkbox" data-setting="compactMode" ${state.preferences.compactMode ? "checked" : ""}/><span class="toggle-control"></span></label></div><div class="settings-danger-zone"><div><strong>Reset workspace data</strong><p>Restore the original sample workspace and discard local changes.</p></div><button class="button button-danger" data-action="reset-workspace">Reset data</button></div></div>`;
  }
  return `<section class="page-content settings-page">${pageHeading("WORKSPACE", "Settings", "Make Nexus feel like your team's space.", "")}<div class="settings-layout"><nav class="settings-nav" aria-label="Settings sections">${tabs.map((item) => `<button class="settings-nav-item ${tab === item.name ? "active" : ""}" data-action="set-settings-tab" data-tab="${item.name}">${icon(item.icon, 16)} ${item.name}${icon("chevronRight", 14)}</button>`).join("")}</nav><article class="surface settings-panel">${content}</article></div></section>`;
}

export function renderNotifications(state) {
  const notifications = [...state.notifications].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, 6);
  const unread = state.notifications.filter((item) => !item.read).length;
  return `<div class="notification-popover"><div class="notification-popover-head"><div><strong>Notifications</strong><span>${unread ? `${unread} unread` : "You're all caught up"}</span></div><button class="text-link" data-action="mark-all-read">Mark all read</button></div><div class="notification-list">${notifications.length ? notifications.map((item) => `<button class="notification-row ${item.read ? "read" : "unread"}" data-action="open-notification" data-id="${escapeHtml(item.id)}"><span class="notification-row-dot">${item.read ? icon("check", 12) : ""}</span><span class="notification-row-copy"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.body)}</span><small>${relativeTime(item.createdAt)}</small></span></button>`).join("") : emptyState({ iconName: "bell", title: "All quiet", body: "New updates will show here." })}</div><button class="notification-footer" data-action="navigate" data-page="activity">Open activity feed ${icon("arrowRight", 14)}</button></div>`;
}

function personOptions(state, selectedId) {
  return state.users.map((user) => `<option value="${escapeHtml(user.id)}" ${selectedId === user.id ? "selected" : ""}>${escapeHtml(user.name)}</option>`).join("");
}

function projectOptions(state, selectedId) {
  return state.projects.map((project) => `<option value="${escapeHtml(project.id)}" ${selectedId === project.id ? "selected" : ""}>${escapeHtml(project.name)}</option>`).join("");
}

function renderTaskDialog(state, taskId) {
  const task = getTask(taskId);
  if (!task) return "";
  const project = getProject(task.projectId);
  const comments = task.comments || [];
  const subtasks = task.subtasks || [];
  return `<dialog class="dialog dialog-drawer" id="task-detail-dialog" aria-labelledby="task-dialog-title"><div class="drawer-topbar"><div class="drawer-breadcrumb">${projectMark(project || { color: "#8290a1", icon: "layers" }, "xs")}<span>${escapeHtml(project?.name || "No project")}</span>${icon("chevronRight", 13)}<span class="task-short-id">${escapeHtml(task.id.toUpperCase())}</span></div><div class="drawer-actions"><button class="icon-button" aria-label="Close task details" data-action="close-dialog">${icon("close", 18)}</button></div></div><div class="drawer-scroll"><div class="task-detail-heading"><span class="task-status-icon task-status-${task.status.toLowerCase().replaceAll(" ", "-")}">${task.status === "Done" ? icon("check", 14) : icon("circle", 16)}</span><h2 id="task-dialog-title" class="sr-only">Task details: ${escapeHtml(task.title)}</h2><span class="detail-task-label">Task details</span></div><label class="sr-only" for="detail-title">Task title</label><input class="detail-title-input" id="detail-title" data-task-field="title" data-focus-key="detail-title" value="${escapeHtml(task.title)}" maxlength="140" aria-label="Task title"/><div class="detail-properties"><label class="detail-property"><span>${icon("circle", 15)} Status</span><select data-task-field="status" data-focus-key="detail-status" aria-label="Task status">${STATUSES.map((status) => `<option ${task.status === status ? "selected" : ""}>${status}</option>`).join("")}</select></label><label class="detail-property"><span>${icon("flag", 15)} Priority</span><select data-task-field="priority" data-focus-key="detail-priority" aria-label="Task priority">${PRIORITIES.map((priority) => `<option ${task.priority === priority ? "selected" : ""}>${priority}</option>`).join("")}</select></label><label class="detail-property"><span>${icon("user", 15)} Assignee</span><select data-task-field="assigneeId" data-focus-key="detail-assignee" aria-label="Task assignee">${personOptions(state, task.assigneeId)}</select></label><label class="detail-property"><span>${icon("layers", 15)} Project</span><select data-task-field="projectId" data-focus-key="detail-project" aria-label="Task project">${projectOptions(state, task.projectId)}</select></label><label class="detail-property"><span>${icon("calendar", 15)} Due date</span><input type="date" data-task-field="dueDate" data-focus-key="detail-date" value="${escapeHtml(task.dueDate || "")}" aria-label="Task due date"/></label><label class="detail-property"><span>${icon("tag", 15)} Tag</span><input data-task-field="tag" data-focus-key="detail-tag" value="${escapeHtml(task.tag || "")}" aria-label="Task tag" maxlength="40"/></label></div><div class="detail-section"><div class="detail-section-title"><h3>Description</h3><span>Rich context</span></div><textarea class="detail-description" data-task-field="description" data-focus-key="detail-description" aria-label="Task description" placeholder="Add context, decisions, or acceptance criteria…">${escapeHtml(task.description || "")}</textarea></div><div class="detail-section"><div class="detail-section-title"><h3>Subtasks <span>${subtasks.filter((item) => item.done).length}/${subtasks.length}</span></h3><button class="text-link" data-action="toggle-subtask-form">${icon("plus", 14)} Add</button></div>${subtasks.length ? `<div class="subtask-list">${subtasks.map((subtask) => `<label class="subtask-row ${subtask.done ? "done" : ""}"><input type="checkbox" data-action="toggle-subtask" data-task-id="${escapeHtml(task.id)}" data-id="${escapeHtml(subtask.id)}" ${subtask.done ? "checked" : ""}/><span>${escapeHtml(subtask.title)}</span></label>`).join("")}</div>` : `<p class="detail-muted">Break this task into smaller steps when it helps.</p>`}${uiSubtaskForm(task.id)}</div><div class="detail-section comments-section"><div class="detail-section-title"><h3>Comments <span>${comments.length}</span></h3><button class="text-link" data-action="comment-help">${icon("help", 14)} Guidelines</button></div>${comments.length ? `<div class="comment-list">${comments.map((comment) => { const author = getUser(comment.authorId); return `<article class="comment-item">${avatar(author, "sm")}<div class="comment-body"><div><strong>${escapeHtml(author?.name || "Teammate")}</strong><span>${relativeTime(comment.createdAt)}</span></div><p>${escapeHtml(comment.text)}</p></div></article>`; }).join("")}</div>` : `<p class="detail-muted">No comments yet. Share a decision or ask a question.</p>`}<form class="comment-form" data-form="comment" data-task-id="${escapeHtml(task.id)}">${avatar(getUser(state.users[0].id), "sm")}<label class="sr-only" for="comment-input">Write a comment</label><textarea id="comment-input" name="comment" placeholder="Leave a comment…" required maxlength="1000" data-focus-key="comment-input"></textarea><button class="button button-primary button-sm" type="submit">Send ${icon("arrowRight", 14)}</button></form></div></div><footer class="drawer-footer"><span>Created ${relativeTime(task.createdAt)}</span><button class="button button-danger-quiet" data-action="delete-task" data-id="${escapeHtml(task.id)}">${icon("trash", 15)} Delete task</button><button class="button button-primary button-sm" data-action="complete-task" data-id="${escapeHtml(task.id)}">${task.status === "Done" ? icon("check", 14) : icon("checkCircle", 15)} ${task.status === "Done" ? "Completed" : "Mark complete"}</button></footer></dialog>`;
}

function uiSubtaskForm(taskId) {
  return `<form class="subtask-add-form hidden" data-form="subtask" data-task-id="${escapeHtml(taskId)}"><label class="sr-only" for="new-subtask">Subtask name</label><input id="new-subtask" name="title" placeholder="Write a subtask…" required maxlength="100"/><button class="icon-button" aria-label="Add subtask" type="submit">${icon("arrowRight", 16)}</button></form>`;
}

function renderTaskCreateDialog(state, ui) {
  const fromStatus = ui.createTaskStatus || "Todo";
  const projectId = ui.createTaskProject || state.projects[0]?.id || "";
  const dueDate = ui.createTaskDate || "";
  return `<dialog class="dialog dialog-form" id="create-task-dialog" aria-labelledby="create-task-title"><div class="dialog-header"><div><span class="dialog-kicker">QUICK CREATE</span><h2 id="create-task-title">New task</h2><p>Give the next step a name and a home.</p></div><button class="icon-button" aria-label="Close" data-action="close-dialog">${icon("close", 18)}</button></div><form class="dialog-form-body" data-form="create-task"><label class="field-label">Task name <span class="required-mark">*</span><input name="title" autofocus required maxlength="140" placeholder="e.g. Review the onboarding flow" data-focus-key="create-task-title"/></label><label class="field-label">Description<textarea name="description" maxlength="1000" placeholder="Add a little context for the team…"></textarea></label><div class="form-field-grid"><label class="field-label">Project<select name="projectId" required>${projectOptions(state, projectId)}</select></label><label class="field-label">Status<select name="status">${STATUSES.map((status) => `<option ${status === fromStatus ? "selected" : ""}>${status}</option>`).join("")}</select></label><label class="field-label">Priority<select name="priority">${PRIORITIES.map((priority) => `<option ${priority === "Medium" ? "selected" : ""}>${priority}</option>`).join("")}</select></label><label class="field-label">Assignee<select name="assigneeId">${personOptions(state, state.users[0]?.id)}</select></label><label class="field-label">Due date<input type="date" name="dueDate" value="${escapeHtml(dueDate)}"/></label><label class="field-label">Tag<input name="tag" maxlength="40" placeholder="e.g. Design"/></label></div><div class="dialog-footer"><span class="form-hint">You can update these details any time.</span><button type="button" class="button button-secondary" data-action="close-dialog">Cancel</button><button class="button button-primary" type="submit">${icon("plus", 15)} Create task</button></div></form></dialog>`;
}

function renderProjectCreateDialog(state, editingId = null) {
  const editing = editingId ? getProject(editingId) : null;
  const title = editing ? "Edit project" : "Create a project";
  const palette = ["#6e83d9", "#5a9c86", "#d28d56", "#9277bf", "#4d91bd", "#c16c83", "#7a9e63", "#6a83a8"];
  return `<dialog class="dialog dialog-form" id="project-dialog" aria-labelledby="project-dialog-title"><div class="dialog-header"><div><span class="dialog-kicker">PROJECT SETUP</span><h2 id="project-dialog-title">${title}</h2><p>${editing ? "Update the details so everyone stays aligned." : "Give your team's work a clear place to move forward."}</p></div><button class="icon-button" aria-label="Close" data-action="close-dialog">${icon("close", 18)}</button></div><form class="dialog-form-body" data-form="${editing ? "edit-project" : "create-project"}" data-project-id="${editing ? escapeHtml(editing.id) : ""}"><label class="field-label">Project name <span class="required-mark">*</span><input name="name" value="${escapeHtml(editing?.name || "")}" required maxlength="80" placeholder="e.g. Customer portal refresh" data-focus-key="project-name"/></label><label class="field-label">Description<textarea name="description" maxlength="400" placeholder="What outcome will this project create?">${escapeHtml(editing?.description || "")}</textarea></label><div class="form-field-grid"><label class="field-label">Project lead<select name="leadId">${personOptions(state, editing?.leadId || state.users[0]?.id)}</select></label><label class="field-label">Status<select name="status">${["Active", "At risk", "Planned", "Completed"].map((status) => `<option ${editing?.status === status ? "selected" : (!editing && status === "Active") ? "selected" : ""}>${status}</option>`).join("")}</select></label><label class="field-label">Due date<input type="date" name="dueDate" value="${escapeHtml(editing?.dueDate || "")}"/></label></div><fieldset class="color-field"><legend>Project color</legend><div class="color-options">${palette.map((color) => `<label><input type="radio" name="color" value="${color}" ${editing?.color === color || (!editing && color === palette[0]) ? "checked" : ""}/><i style="--swatch:${color}"></i><span class="sr-only">${color}</span></label>`).join("")}</div></fieldset><div class="dialog-footer"><span class="form-hint">${editing ? "Your changes update the project workspace." : "You can invite teammates after creating the project."}</span><button type="button" class="button button-secondary" data-action="close-dialog">Cancel</button><button type="submit" class="button button-primary">${editing ? "Save project" : `${icon("plus", 15)} Create project`}</button></div></form></dialog>`;
}

function renderGlobalSearch(state, ui) {
  const query = (ui.globalSearch || "").trim();
  const projects = query ? state.projects.filter((project) => matchesQuery(`${project.name} ${project.description}`, query)).slice(0, 4) : [];
  const tasks = query ? state.tasks.filter((task) => matchesQuery(`${task.title} ${task.tag}`, query)).slice(0, 6) : [];
  return `<dialog class="dialog search-dialog" id="global-search-dialog" aria-labelledby="search-dialog-title"><div class="global-search-input">${icon("search", 19)}<label class="sr-only" id="search-dialog-title" for="global-search-input">Search workspace</label><input id="global-search-input" type="search" data-search="global" data-focus-key="global-search" value="${escapeHtml(ui.globalSearch || "")}" placeholder="Search projects, tasks, and people…" autocomplete="off"/><kbd>ESC</kbd><button class="icon-button icon-button-xs" aria-label="Close search" data-action="close-dialog">${icon("close", 16)}</button></div>${query ? `<div class="global-search-results">${projects.length ? `<div class="search-result-group"><div class="search-result-heading">PROJECTS <span>${projects.length}</span></div>${projects.map((project) => `<button data-action="open-project" data-id="${escapeHtml(project.id)}" data-close-search="true">${projectMark(project, "sm")}<span><strong>${escapeHtml(project.name)}</strong><small>${escapeHtml(project.description)}</small></span>${icon("arrowUpRight", 15)}</button>`).join("")}</div>` : ""}${tasks.length ? `<div class="search-result-group"><div class="search-result-heading">TASKS <span>${tasks.length}</span></div>${tasks.map((task) => `<button data-action="open-task" data-id="${escapeHtml(task.id)}" data-close-search="true"><span class="task-status-icon task-status-${task.status.toLowerCase().replaceAll(" ", "-")}">${task.status === "Done" ? icon("check", 12) : icon("circle", 14)}</span><span><strong>${escapeHtml(task.title)}</strong><small>${escapeHtml(getProject(task.projectId)?.name || "")} · ${task.status}</small></span>${icon("arrowUpRight", 15)}</button>`).join("")}</div>` : ""}${!projects.length && !tasks.length ? emptyState({ iconName: "search", title: "No results found", body: "Try a different name, task, or keyword." }) : ""}</div>` : `<div class="search-empty"><span class="search-empty-icon">${icon("sparkle", 19)}</span><p>Search across <strong>${state.projects.length} projects</strong> and <strong>${state.tasks.length} tasks</strong></p><div class="search-suggestions"><span>Try</span><button data-action="search-example" data-query="onboarding">onboarding</button><button data-action="search-example" data-query="billing">billing</button><button data-action="search-example" data-query="research">research</button></div></div>`}<div class="search-dialog-footer"><span>${icon("arrowUpRight", 13)} to open</span><span>Searches update as you type</span></div></dialog>`;
}

export function renderDialogs(state, ui) {
  return `<div id="dialog-layer">${ui.taskDetailId ? renderTaskDialog(state, ui.taskDetailId) : ""}${ui.modal === "create-task" ? renderTaskCreateDialog(state, ui) : ""}${ui.modal === "create-project" ? renderProjectCreateDialog(state) : ""}${ui.modal === "edit-project" ? renderProjectCreateDialog(state, ui.editingProjectId) : ""}${ui.searchOpen ? renderGlobalSearch(state, ui) : ""}${ui.modal === "help" ? `<dialog class="dialog help-dialog" id="help-dialog"><div class="dialog-header"><div><span class="dialog-kicker">QUICK REFERENCE</span><h2>Keyboard shortcuts</h2><p>Keep your hands on the work.</p></div><button class="icon-button" aria-label="Close" data-action="close-dialog">${icon("close", 18)}</button></div><div class="shortcut-list"><div><span>Search anywhere</span><kbd>⌘ K</kbd></div><div><span>Create a new task</span><kbd>C</kbd></div><div><span>Close dialog or panel</span><kbd>Esc</kbd></div><div><span>Move between controls</span><kbd>Tab</kbd></div></div></dialog>` : ""}</div>`;
}

export function renderPage(state, route, ui) {
  if (route.page === "overview") return renderOverview(state);
  if (route.page === "projects") return renderProjects(state, ui);
  if (route.page === "tasks") return renderTasks(state, ui);
  if (route.page === "board") return `<section class="page-content">${pageHeading("WORKSPACE", "Board", "Move work forward with a clear view of every stage.", `<button class="button button-primary" data-action="create-task">${icon("plus", 16)} New task</button>`)}${renderBoard(state, ui)}</section>`;
  if (route.page === "project") return renderProjectDetail(state, ui, route.projectId);
  if (route.page === "calendar") return renderCalendar(state, ui);
  if (route.page === "analytics") return renderAnalytics(state);
  if (route.page === "activity") return renderActivityPage(state, ui);
  if (route.page === "settings") return renderSettings(state, ui);
  return renderOverview(state);
}
